template <typename Value>
[[nodiscard]] ReadonlyObjectValue readonly_nested_object_value(const Value& value) {
  if constexpr (is_std_optional<std::remove_cvref_t<Value>>::value) {
    return value ? readonly_nested_object_value(*value)
                 : ReadonlyObjectValue{AnyKind::undefined, true, {}, {}};
  } else if constexpr (requires { { value.shared_owner() } -> std::convertible_to<std::shared_ptr<RowOwner>>; }) {
    return {AnyKind::object, bool(value.shared_owner()), value.shared_owner(), value.shared_native_object()};
  } else {
    const auto erased = any_from(value);
    if (!erased) return {};
    auto owner = std::static_pointer_cast<RowOwner>(erased->erased_row_owner());
    auto retained = owner ? owner->native_object() : nullptr;
    return {erased->kind(), true, std::move(owner), std::move(retained)};
  }
}
